template <typename Char, typename... T> struct tuple_join_view : detail::view {
  const std::tuple<T...>& tuple;
  basic_string_view<Char> sep;

  tuple_join_view(const std::tuple<T...>& t, basic_string_view<Char> s)
      : tuple(t), sep{s} {}
};

template <typename Char, typename... T>
using tuple_arg_join = tuple_join_view<Char, T...>;

template <typename Char, typename... T>
struct formatter<tuple_join_view<Char, T...>, Char> {
 private:
  using element_formatters = std::tuple<formatter<remove_cvref_t<T>, Char>...>;

  element_formatters element_formatters_;

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse_element_formatters(
      ParseContext&, std::integral_constant<size_t, 0>)
      -> typename ParseContext::iterator {
    // A parse context's begin() is not advanced by element formatters' parse
    // functions so they all parse the same spec and the returned iterator
    // points to '}'.
    return {};
  }

  template <typename ParseContext, size_t N>
  FMT_CONSTEXPR auto parse_element_formatters(
      ParseContext& ctx, std::integral_constant<size_t, N>)
      -> typename ParseContext::iterator {
    auto end = parse_element_formatters(
        ctx, std::integral_constant<size_t, N - 1>{});
    std::get<sizeof...(T) - N>(element_formatters_).parse(ctx);
    return end;
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>&, FormatContext& ctx,
              std::integral_constant<size_t, 0>)
      -> typename FormatContext::iterator {
    return ctx.out();
  }

  template <typename FormatContext, size_t N>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
              std::integral_constant<size_t, N>)
      -> typename FormatContext::iterator {
    using std::get;
    auto out = get<sizeof...(T) - N>(element_formatters_)
                   .format(get<sizeof...(T) - N>(value.tuple), ctx);
    if (N > 1) {
      out = detail::copy_str<Char>(value.sep.begin(), value.sep.end(), out);
      ctx.advance_to(out);
      out = format(value, ctx, std::integral_constant<size_t, N - 1>{});
    }
    return out;
  }

 public:
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return parse_element_formatters(
        ctx, std::integral_constant<size_t, sizeof...(T)>{});
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx) ->
      typename FormatContext::iterator {
    return format(value, ctx, std::integral_constant<size_t, sizeof...(T)>{});
  }
};

